local CoffeeRoaster = {}
local PRODUCTS = {
    plain_roasted_beans = { name = "Navadna pražena zrna", woodCost = 1, time = 3, cost = 40, happiness = 2, food = 8, description = "Navadna pražena kavnina zrna za trgovce." },
    ground_coffee_jar = { name = "Mleta kava v kozarcu", woodCost = 1, glassCost = 1, time = 5, cost = 110, happiness = 3, food = 14, prestige = 2, description = "Mleta kava v steklenem kozarcu za trgovce." },
    silver_lidded_coffee = { name = "Srebrnopokrovka kava", woodCost = 1, glassCost = 1, silverCost = 1, time = 8, cost = 280, happiness = 4, food = 20, prestige = 6, description = "Srebrnopokrovka kava za plemiče." },
    gold_trimmed_coffee = { name = "Zlatookrasna kava", woodCost = 1, glassCost = 1, goldCost = 1, silverCost = 1, time = 12, cost = 680, happiness = 5, food = 28, prestige = 14, description = "Zlatookrasna kava za visoke plemiče." },
    jewel_lid_coffee = { name = "Draguljnopokrovka kava", woodCost = 1, glassCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 16, cost = 1500, happiness = 7, food = 40, prestige = 26, description = "Kava z draguljnim pokrovom za visoko plemstvo." },
    royal_grand_coffee = { name = "Kraljevski veliki kava", woodCost = 2, glassCost = 3, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 1, time = 23, cost = 3700, happiness = 12, food = 60, prestige = 56, description = "Veliki kraljevski kavni zaboj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    roaster_cottage = { name = "Pražilna koča", cost = { gold = 220, wood = 120, stone = 100, glass = 4 }, upkeep = 5, qualityBonus = 5 },
    coffee_house = { name = "Kavarna", cost = { gold = 820, wood = 240, stone = 240, silver = 6, glass = 8 }, upkeep = 19, qualityBonus = 18 },
    confectioner_atelier = { name = "Konditorski atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_coffee_palace = { name = "Kraljevska kavarna palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
CoffeeRoaster.woodStock = 14; CoffeeRoaster.glassStock = 12; CoffeeRoaster.silverStock = 8; CoffeeRoaster.goldStock = 6; CoffeeRoaster.jewelStock = 4; CoffeeRoaster.pearlStock = 4
CoffeeRoaster.productStock = {}; CoffeeRoaster.buildings = {}; CoffeeRoaster.maker = nil; CoffeeRoaster.activeMaking = {}; CoffeeRoaster.totalProducts = 0; CoffeeRoaster.dayTimer = 0
function CoffeeRoaster.init() CoffeeRoaster.woodStock=14; CoffeeRoaster.glassStock=12; CoffeeRoaster.silverStock=8; CoffeeRoaster.goldStock=6; CoffeeRoaster.jewelStock=4; CoffeeRoaster.pearlStock=4; CoffeeRoaster.productStock={}; CoffeeRoaster.buildings={}; CoffeeRoaster.maker=nil; CoffeeRoaster.activeMaking={}; CoffeeRoaster.totalProducts=0; CoffeeRoaster.dayTimer=0; print("[CoffeeRoaster] Royal Coffee Roaster System initialized (6 products, 4 buildings)") end
function CoffeeRoaster.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoffeeRoaster.maker={name=n or ("Kavarnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kavarnar najet: %s (spretnost: %d)",CoffeeRoaster.maker.name,s),"success") end; return true end
function CoffeeRoaster.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoffeeRoaster.build(id) local ok,e=CoffeeRoaster.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoffeeRoaster.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoffeeRoaster.getQualityBonus() local b=0; for _,bd in ipairs(CoffeeRoaster.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoffeeRoaster.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CoffeeRoaster.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.glassCost and CoffeeRoaster.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and CoffeeRoaster.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoffeeRoaster.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoffeeRoaster.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoffeeRoaster.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoffeeRoaster.buildings==0 then return false,"Potrebna pražilna koča" end; if not CoffeeRoaster.maker then return false,"Potreben kavarnar" end; return true end
function CoffeeRoaster.make(pt,qty) qty=qty or 1; local ok,e=CoffeeRoaster.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CoffeeRoaster.woodStock=CoffeeRoaster.woodStock-d.woodCost*qty end; if d.glassCost then CoffeeRoaster.glassStock=CoffeeRoaster.glassStock-d.glassCost*qty end; if d.silverCost then CoffeeRoaster.silverStock=CoffeeRoaster.silverStock-d.silverCost*qty end; if d.goldCost then CoffeeRoaster.goldStock=CoffeeRoaster.goldStock-d.goldCost*qty end; if d.jewelCost then CoffeeRoaster.jewelStock=CoffeeRoaster.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoffeeRoaster.pearlStock=CoffeeRoaster.pearlStock-d.pearlCost*qty end; local t=d.time; if CoffeeRoaster.maker then t=math.max(1,t-math.floor(CoffeeRoaster.maker.skill/13)) end; table.insert(CoffeeRoaster.activeMaking,{id="coffee_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Praženje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoffeeRoaster.completeMaking(m) local q=1.0+(CoffeeRoaster.getQualityBonus()/100); if CoffeeRoaster.maker then q=q+(CoffeeRoaster.maker.skill/150) end; q=math.min(2.4,q); CoffeeRoaster.productStock[m.productType]=(CoffeeRoaster.productStock[m.productType] or 0)+m.quantity; CoffeeRoaster.totalProducts=CoffeeRoaster.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoffeeRoaster.maker then CoffeeRoaster.maker.itemsMade=CoffeeRoaster.maker.itemsMade+m.quantity; if math.random()<0.25 then CoffeeRoaster.maker.skill=math.min(100,CoffeeRoaster.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kava pripravljena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coffee.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function CoffeeRoaster.update(dt) if not _G.state then return end; CoffeeRoaster.dayTimer=CoffeeRoaster.dayTimer+dt; if CoffeeRoaster.dayTimer>=30 then CoffeeRoaster.dayTimer=0; for i=#CoffeeRoaster.activeMaking,1,-1 do local m=CoffeeRoaster.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoffeeRoaster.completeMaking(m); table.remove(CoffeeRoaster.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoffeeRoaster.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoffeeRoaster.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoffeeRoaster.getStats() return {woodStock=CoffeeRoaster.woodStock,glassStock=CoffeeRoaster.glassStock,silverStock=CoffeeRoaster.silverStock,goldStock=CoffeeRoaster.goldStock,jewelStock=CoffeeRoaster.jewelStock,pearlStock=CoffeeRoaster.pearlStock,productStock=CoffeeRoaster.productStock,numBuildings=#CoffeeRoaster.buildings,hasMaker=CoffeeRoaster.maker~=nil,makerName=CoffeeRoaster.maker and CoffeeRoaster.maker.name or "—",makerSkill=CoffeeRoaster.maker and CoffeeRoaster.maker.skill or 0,activeMaking=#CoffeeRoaster.activeMaking,totalProducts=CoffeeRoaster.totalProducts} end
return CoffeeRoaster
